// ==UserScript==
// @name         YouTube自动中文字幕
// @description  自动开启YouTube中文字幕，无中文字幕时自动翻译中文。
// @icon         data:image/png;base64,
// @version      3.2.1
// @author       jbaoyin
// @namespace    https://github.com/jbaoyin/userscripts
// @license      MIT
// @match        https://www.youtube.com/*
// @grant        none
// @downloadURL  https://github.com/jbaoyin/userscripts/raw/refs/heads/main/youtube-auto-subtitles.user.js
// @updateURL    https://github.com/jbaoyin/userscripts/raw/refs/heads/main/youtube-auto-subtitles.user.js
// ==/UserScript==

(function () {
    "use strict";

    const CONFIG = {
        chinese: ["中文(简体)", "中文（简体）", "简体中文", "Chinese (Simplified)"],
        translate: ["自动翻译", "Auto-translate", "Auto translate"],
        subtitle: ["字幕", "Subtitles", "Captions"]
    };

    let lastVideo = "";
    let isRunning = false;

    const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
    const normalize = text => (text || "").replace(/\s/g, "").replace(/（/g, "(").replace(/）/g, ")").toLowerCase();

    function toast(message) {
        document.querySelector("#yt-auto-toast")?.remove();

        const box = document.createElement("div");
        box.id = "yt-auto-toast";
        box.textContent = message;

        Object.assign(box.style, {
            position: "fixed", top: "80px", right: "20px", zIndex: "999999",
            background: "rgba(0,0,0,.85)", color: "#fff", padding: "10px 15px",
            borderRadius: "8px", fontSize: "14px", transition: "opacity 0.3s ease"
        });

        document.body.appendChild(box);
        setTimeout(() => {
            box.style.opacity = "0";
            setTimeout(() => box.remove(), 300);
        }, 2500);
    }

    async function waitFor(selector, timeout = 6000, interval = 150) {
        const start = Date.now();
        while (Date.now() - start < timeout) {
            const el = document.querySelector(selector);
            if (el) return el;
            await sleep(interval);
        }
        return null;
    }

    function findMenuItem(keys) {
        for (const item of document.querySelectorAll(".ytp-popup.ytp-settings-menu .ytp-menuitem")) {
            const text = normalize(item.innerText);
            if (keys.some(key => text.includes(normalize(key)))) return item;
        }
        return null;
    }

    async function toggleSettings(open) {
        const btn = document.querySelector(".ytp-settings-button");
        if (!btn) return false;
        
        const menu = document.querySelector(".ytp-popup.ytp-settings-menu");
        const currentlyOpen = menu && menu.style.display !== "none";
        
        if (currentlyOpen !== open) {
            btn.click();
            await waitFor(".ytp-popup.ytp-settings-menu", 2000, 100);
        }
        return true;
    }

    async function selectChinese() {
        let item = findMenuItem(CONFIG.chinese);
        if (item) {
            item.click();
            return "中文字幕";
        }

        item = findMenuItem(CONFIG.translate);
        if (item) {
            item.click();
            const start = Date.now();
            while (Date.now() - start < 1500) {
                await sleep(100);
                const chineseItem = findMenuItem(CONFIG.chinese);
                if (chineseItem) {
                    chineseItem.click();
                    return "自动翻译中文";
                }
            }
        }
        return null;
    }

    async function run() {
        if (location.pathname !== "/watch" || isRunning) return;
        
        const videoId = new URLSearchParams(location.search).get("v");
        if (!videoId || videoId === lastVideo) return;

        isRunning = true;
        lastVideo = videoId;

        try {
            if (!(await waitFor("video", 10000))) return;
            await sleep(800);

            const subBtn = document.querySelector(".ytp-subtitles-button");
            if (subBtn && subBtn.getAttribute("aria-pressed") === "false") {
                subBtn.click();
                await sleep(300);
            }

            if (!(await toggleSettings(true))) return;
            await sleep(200);

            const subtitleItem = findMenuItem(CONFIG.subtitle);
            if (!subtitleItem) {
                await toggleSettings(false);
                toast("ℹ️ 当前视频没有字幕");
                return;
            }

            subtitleItem.click();
            await sleep(300);

            const result = await selectChinese();
            await toggleSettings(false);

            if (result) {
                toast(`✅ 已开启${result}`);
            } else {
                toast("⚠️ 未找到中文选项");
            }
        } catch (e) {
            // 静默处理，避免干扰浏览体验
        } finally {
            isRunning = false;
        }
    }

    // 路由监听（单页应用跳转捕获）
    let lastPath = location.href;
    const checkPageChange = () => {
        if (location.href !== lastPath) {
            lastPath = location.href;
            if (location.pathname === "/watch") setTimeout(run, 1200);
        }
    };

    ["pushState", "replaceState"].forEach(method => {
        const original = history[method];
        history[method] = function() {
            original.apply(this, arguments);
            checkPageChange();
        };
    });

    window.addEventListener("popstate", checkPageChange);
    setInterval(checkPageChange, 1500);

    if (location.pathname === "/watch") {
        setTimeout(run, 1500);
    }
})();
